   301  M3Result  Read_u8  (u8 * o_value, bytes_t  * io_bytes, cbytes_t i_end)
   302  {
   303      const u8 * ptr = * io_bytes;
   304
   305      if (ptr < i_end)
   306      {
   307          * o_value = * ptr;
   308          * io_bytes = ptr + 1;
   309
   310          return m3Err_none;
   311      }
   312      else return m3Err_wasmUnderrun;
   313  }
