   315  M3Result  Read_opcode  (m3opcode_t * o_value, bytes_t  * io_bytes, cbytes_t i_end)
   316  {
   317      const u8 * ptr = * io_bytes;
   318
   319      if (ptr < i_end)
   320      {
   321          m3opcode_t opcode = * ptr++;
   322
   323  #ifndef d_m3CompileExtendedOpcode
   324          if (UNLIKELY(opcode == 0xFC))
   325          {
   326              if (ptr < i_end)
   327              {
   328                  opcode = (opcode << 8) | (* ptr++);
   329              }
   330              else return m3Err_wasmUnderrun;
   331          }
   332  #endif
   333          * o_value = opcode;
   334          * io_bytes = ptr;
   335
   336          return m3Err_none;
   337      }
   338      else return m3Err_wasmUnderrun;
   339  }
